"""
Setup
---
Simple setup tool.
Made for people who don't know git.
Can also be useful as the setuper auto checks if all needed files are there.
"""
import os
import subprocess
import tkinter as tk
import base64
from PIL import Image, ImageTk
import io
import tkinter.font as tkFont
import time
import sys

"""
Ok so why tf did I paste an entire image here?
Cuz I want this to be portable ykyk.
Like you could just take this file anywhere and yea install Water-Fish without taking a seperate waterfish.png with you.
Yes Imma be trynna compress the image, besides it's just pixel art.
"""
data = ""

img = Image.open(io.BytesIO(base64.b64decode(data)))
img = img.resize((200,200))

def start():
    try:
        subprocess.run(["git", "clone", "https://github.com/CoolGuy158-Git/Water-Fish"])
        text.config(text="Cloned WaterFish repo")
    except Exception as e:
        text.config(text=f'Failed due to {e}')
    root.update()
    time.sleep(1)
    os.remove('Water-Fish/setup.py')
    base = "Water-Fish"
    paths = ['Water-Fish/, main.py, README.md, CONTRIBUTING.md, Requirements.txt, info.html, images/waterfish.ico, images/waterfish.png, system/settings.txt, audio/rickroll.mp3, wfmodules/Welcome.py, wfmodules/secrets.py, wfmodules/history.py, wfmodules/command.py, wfmodules/checkonline.py, wfmodules/startup.py, wfmodules/remora.py, wfmodules/stars.py, wfmodules/reload.py, wfmodules/logger.py, wfmodules/dragndrop.py, wfmodules/mp3play.py, wfmodules/mdrenderer.py']

    for p in paths:
        fullp = os.path.join(base,p)
        if os.path.isfile(fullp):
            text.config(text=f'Found: {fullp}')
        else:
            text.config(text=f"Missing: {fullp}")
    root.update()
    time.sleep(1)
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "-r", "Water-Fish/Requirements.txt"])
        text.config(text='Installed dependencies successfully')
    except Exception as e:
        text.config(text=f'Unable to install dependencies due to {e}')
    root.update()
    time.sleep(1)
    try:
        subprocess.run([sys.executable, "Water-Fish/main.py"])
        root.update()
        time.sleep(1)
        root.destroy()
    except Exception as e:
        text.config(text=f'Failed to start main.py due to {e}')

root = tk.Tk()
root.geometry('600x400')
root.resizable(False, False)
photo = ImageTk.PhotoImage(img)
imgl = tk.Label(root, image=photo)
imgl.pack()
bottomcolor = tk.Frame(root, height=200, bg='gray', borderwidth=2, relief="solid")
bottomcolor.pack(fill='x')
bottomcolor.pack_propagate(False)
text = tk.Label(bottomcolor, text='Start installation?', bg='gray', font=tkFont.Font(size=24))
text.pack(pady=10)
btn = tk.Button(bottomcolor, text='Start', font=tkFont.Font(size=24), command=lambda: start())
btn.pack()
root.mainloop()
